SELECT EXISTS (SELECT 1 FROM transcript_archives WHERE organization_uuid = #{archive.OrganizationUUID}
AND workspace_uuid = #{archive.WorkspaceUUID} AND code_session_uuid = #{archive.CodeSessionUUID}
AND state <> 'deleting' AND from_sequence_num <= #{archive.ToSequence} AND to_sequence_num >= #{archive.FromSequence})
